<?php elseif($page==='verify'):?><div class="symbol" aria-hidden="true">✉</div><p>If your account needs verification, we’ve sent you a confirmation email. Open it and press <strong>Verify email</strong>, then sign in.</p><p class="fine">Check spam too. Already registered? Sign in or reset your password.</p><details><summary>Need another email?</summary><?php form_start();input('email','Email address','email','email',254);?><button class="primary">Resend verification</button></form></details><a class="primary link-button" href="?page=signin">Go to sign in</a>
<?php elseif($page==='signin'):?><p>Sign in to your FaraiOS account.</p><?php form_start();input('email','Email address','email','email',254);input('password','Password','password','current-password',128);?><a class="forgot" href="?page=forgot">Forgot password?</a><button class="primary">Sign in</button></form><p class="switch"><a href="?page=verify">Resend verification</a> · <a href="?page=signup">Create an account</a></p>
<?php elseif($page==='forgot'):?><p>Enter your account email. We’ll send a secure link to choose a new password.</p><?php form_start();input('email','Email address','email','email',254);?><button class="primary">Send reset link</button></form><p class="switch"><a href="?page=signin">Back to sign in</a></p>
<?php elseif($page==='confirm'):?><p>Press Continue to verify this email link. This keeps email security scanners from using your link before you do.</p><?php form_start();?><input type="hidden" name="token_hash" id="token_hash" value="<?=esc((string)($_POST['token_hash']??''))?>"><input type="hidden" name="type" id="type" value="<?=esc((string)($_POST['type']??''))?>"><button class="primary" id="confirm-button" disabled>Continue</button></form><p class="fine" id="link-status">Checking your link…</p><p class="switch"><a href="?page=verify">Request verification</a> · <a href="?page=forgot">Reset password</a></p>
