<?php elseif($page==='business' && $u):?><p>Just two details to make this space yours.</p><?php form_start();input('business_name','Business name','text','organization');?><label for="business_type">Business type</label><select id="business_type" name="business_type" required><option value="">Choose a type</option><?php foreach(['cleaning'=>'Cleaning','beauty-wellness'=>'Beauty & wellness','home-maintenance-trades'=>'Home maintenance & trades','other'=>'Other'] as $key=>$label):?><option value="<?=$key?>" <?=($_POST['business_type']??'')===$key?'selected':''?>><?=esc($label)?></option><?php endforeach;?></select><small>You can use your trading name.</small><button class="primary">Create business</button></form>
<?php elseif($page==='welcome' && $b):?><div class="symbol" aria-hidden="true">✓</div><h2><?=esc($b['name'])?></h2><p>Your email is verified and your business has been saved.</p><div class="saved"><span>Account</span><strong><?=esc($u['email'])?></strong><span>Business</span><strong><?=esc($b['name'])?></strong></div><p class="fine">You’re all set for this first step. More tools will follow.</p>
